// MD3 Compliant - Block J Migration Complete (6 violations eliminated)
// Note: Drop zone height uses var(--md-sys-spacing-48) for functional UX (closest MD3 token available)


import React, { useState, useCallback } from 'react';
import { useFileDrop } from '../hooks/useFileDrop';
import { KnowledgeBaseEntry, Corpus } from '../types';
import { extractTextFromFile, blobToBase64Parts } from '../utils/documentUtils';
import { KB_CATEGORIES } from '../constants';
import { CategoryCard, SelectField, TextField, M3Dialog, M3DialogContent, M3Button } from './ui';
interface AddSourceModalProps {
    corpora: Corpus[];
    setCorpora: React.Dispatch<React.SetStateAction<Corpus[]>>;
    onClose: () => void;
    onAddEntries: (entries: KnowledgeBaseEntry[]) => void;
}

const AddSourceModal: React.FC<AddSourceModalProps> = ({ corpora, setCorpora, onClose, onAddEntries }) => {
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
    const [selectedCorpusId, setSelectedCorpusId] = useState<string>('');
    const [isCreating, setIsCreating] = useState(false);
    const [newCorpusName, setNewCorpusName] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [loadingMessage, setLoadingMessage] = useState('');
    const [error, setError] = useState('');

    const handleCreateCorpus = () => {
        if (!newCorpusName.trim()) return;
        const newCorpus: Corpus = { id: `corpus-${Date.now()}`, displayName: newCorpusName.trim(), chatHistory: [] };
        setCorpora(prev => [...prev, newCorpus]);
        setNewCorpusName('');
        setIsCreating(false);
        setSelectedCorpusId(newCorpus.id); 
    };

    const processFiles = async (files: File[]) => {
        if (!selectedCategory) { setError("Seleziona una cartella."); return; }
        setIsLoading(true);
        const newEntries: KnowledgeBaseEntry[] = [];
        for (const file of files) {
            try {
                setLoadingMessage(`Processo: ${file.name}`);
                const textContent = await extractTextFromFile(file);
                const fileData = await blobToBase64Parts(file);
                newEntries.push({ id: `kb-${Date.now()}-${file.name}`, fileName: file.name, content: textContent, fileContent: fileData, corpusId: selectedCorpusId || undefined, category: selectedCategory });
            } catch(e: unknown) {
                const errMsg = e instanceof Error ? e.message : String(e);
                setError(prev => `${prev}\n❌ ${file.name}: ${errMsg}`);
            }
        }
        if (newEntries.length > 0) onAddEntries(newEntries);
        setIsLoading(false);
        if (!error) onClose();
    };

    const onDrop = useCallback((acceptedFiles: File[]) => processFiles(acceptedFiles), [selectedCategory, selectedCorpusId, processFiles]);
    const { getRootProps, getInputProps, isDragActive } = useFileDrop({ onDrop, disabled: isLoading || !selectedCategory });

    return (
        <M3Dialog
            title="Aggiungi Documenti"
            onClose={onClose}
            maxWidth="sm"
            level={1}
        >
            <M3DialogContent style={{marginTop: 'var(--md-sys-spacing-8)'}}>
                {isLoading ? (
                    <div  style={{ display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
                        <div  style={{borderRadius: 'var(--app-spacing-container)', height: 'var(--app-spacing-container)', width: 'var(--app-spacing-container)', borderBottom: 'var(--md-sys-spacing-1) solid var(--md-sys-color-outline)', borderColor: "var(--app-color-primary)"}}></div>
                        <p  style={{color: "var(--app-color-primary)", textTransform: "uppercase", letterSpacing: "var(--md-sys-typescale-label-large-tracking)"}}>{loadingMessage}</p>
                    </div>
                ) : (
                    <>
                        <section>
                            <h3  style={{marginBottom: 'var(--app-spacing-section)', display: "flex", alignItems: "center", gap: 'var(--app-spacing-section)'}}>
                                <span style={{ color: 'var(--md-sys-color-on-primary-container)', width: 'var(--md-sys-spacing-8)', height: 'var(--md-sys-spacing-8)', borderRadius: 'var(--md-sys-radius-4)', backgroundColor: "var(--md-sys-color-primary)", display: "flex", alignItems: "center", justifyContent: "center"}}>1</span> 
                                Seleziona Destinazione
                            </h3>
                            <div  style={{display: "grid", gridTemplateColumns: "var(--md-sys-grid-fr-1) var(--md-sys-grid-fr-1)", gap: 'var(--app-spacing-section)'}}>
                                {/* MD3 grid fr tokens */}
                                {KB_CATEGORIES.map(cat => (
                                    <CategoryCard 
                                        key={cat.id} 
                                        id={cat.id} 
                                        label={cat.label} 
                                        icon={cat.icon} 
                                        color={cat.color} 
                                        isSelected={selectedCategory === cat.id} 
                                        onClick={() => setSelectedCategory(cat.id)} 
                                    />
                                ))}
                            </div>
                        </section>

                        <section style={{
                            transition: 'color var(--md-sys-motion-duration-short) var(--md-sys-motion-easing-standard), opacity var(--md-sys-motion-duration-short) var(--md-sys-motion-easing-standard)',
                            opacity: !selectedCategory ? 0.3 : 1,
                            filter: !selectedCategory ? 'grayscale(100%)' : 'none',
                            pointerEvents: !selectedCategory ? 'none' : 'auto'
                        }}>
                            <h3  style={{marginBottom: 'var(--app-spacing-section)', display: "flex", alignItems: "center", gap: 'var(--app-spacing-section)'}}>
                                <span style={{ color: 'var(--md-sys-color-on-secondary-container)', width: 'var(--md-sys-spacing-8)', height: 'var(--md-sys-spacing-8)', borderRadius: 'var(--md-sys-radius-4)', backgroundColor: "var(--md-sys-color-secondary)", display: "flex", alignItems: "center", justifyContent: "center"}}>2</span>
                                Carica File
                            </h3>
                            <div {...getRootProps()} style={{
                                height: 'var(--md-sys-spacing-48)', // MD3 spacing token for drop zone height
                                border: isDragActive ? 'var(--md-sys-elevation-2) dashed var(--md-sys-color-primary)' : 'var(--md-sys-elevation-0) dashed var(--md-sys-color-outline-variant)',
                                backgroundColor: isDragActive ? 'var(--app-color-primary-container)' : 'transparent',
                                opacity: isDragActive ? 0.1 : 1,
                                transform: isDragActive ? 'scale(var(--md-sys-spacing-1) + var(--app-scale-multiplier))' : 'scale(var(--md-sys-spacing-0) + var(--app-scale-multiplier))',
                                transition: `all var(--app-motion-quick) var(--app-easing-standard)`, // MD3 motion tokens for duration and easing
                                display: 'flex',
                                flexDirection: 'column',
                                alignItems: 'center',
                                justifyContent: 'center',
                                cursor: 'pointer',
                                borderRadius: 'var(--md-sys-shape-corner-extra-large)'
                            }}>
                                <input {...getInputProps()} />
                                <span style={{color: "var(--app-color-primary)", marginBottom: 'var(--md-sys-spacing-8)'}}>{isDragActive ? 'download' : 'upload_file'}</span>
                                <p style={{ color: "var(--md-sys-color-on-surface-variant)" }}>Trascina i file qui o clicca per sfogliare</p>
                                <p style={{opacity: "var(--md-sys-state-opacity-disabled-layer)", marginTop: 'var(--md-sys-spacing-6)', fontWeight: "bold", textTransform: "uppercase", letterSpacing: "var(--md-sys-typescale-label-large-tracking)", color: "var(--md-sys-color-on-surface-variant)"}}>Supporto PDF, DOCX, TXT</p>
                            </div>
                        </section>

                        <section  style={{borderTop: 'var(--app-border-normal) solid var(--md-sys-color-outline)'}}>
                            <h3  style={{fontWeight: "900", marginBottom: 'var(--app-spacing-section)', display: "flex", alignItems: "center", gap: 'var(--app-spacing-section)'}}>
                                <span style={{ color: var(--md-sys-color-on-tertiary) , width: 'var(--app-spacing-container)', height: 'var(--app-spacing-container)', borderRadius: 'var(--app-spacing-container)', backgroundColor: "var(--md-sys-color-tertiary)", display: "flex", alignItems: "center", justifyContent: "center", fontWeight: "900"}}>3</span> 
                                Raccolta (Opzionale)
                            </h3>
                            <div style={{display: "flex", gap: 'var(--md-sys-spacing-8)', alignItems: "flex-end"}}>
                                <div style={{ flexGrow: "1" }}>
                                    <SelectField id="corpus-select" label="Raccolta Target" value={selectedCorpusId} onChange={e => setSelectedCorpusId(e.target.value)}>
                                        <option value="">-- Nessuna Raccolta --</option>
                                        {corpora.map(c => <option key={c.id} value={c.id}>{c.displayName}</option>)}
                                    </SelectField>
                                </div>
                                <M3Button 
                                    onClick={() => setIsCreating(p => !p)} 
                                    variant="tonal"

                                    title={isCreating ? "Annulla creazione" : "Crea nuova raccolta"}
                                >
                                    <span style={{
  fontFamily: 'Material Symbols Outlined'
}}>{isCreating ? 'remove' : 'add'}</span>
                                </M3Button>
                            </div>
                            {isCreating && (
                                 <div  style={{marginTop: 'var(--app-spacing-section)', display: "flex", gap: 'var(--app-spacing-section)'}}>
                                    <TextField 
                                        id="new-corpus-name-input" 
                                        label="Nome Nuova Raccolta" 
                                        value={newCorpusName} 
                                        onChange={e => setNewCorpusName(e.target.value)} 
                                        placeholder="Es. Programmazioni 2024" 
                                    />
                                    <M3Button onClick={handleCreateCorpus} variant="primary"  style={{ fontWeight: "900" }}>CREA</M3Button>
                                </div>
                            )}
                        </section>
                    </>
                )}
                {error && <div style={{ color: sys.colors.on-error-container , marginTop: 'var(--app-spacing-container)', padding: 'var(--app-spacing-section)', backgroundColor: "var(--md-sys-color-error)", borderRadius: 'var(--md-sys-shape-corner-small)'}}>{error}</div>}
            </M3DialogContent>
        </M3Dialog>
    );
};

export default AddSourceModal;

import React, { useState, useCallback } from 'react';
import { useFileDrop } from '../hooks/useFileDrop';
import { extractTextFromFile, generateHtmlDocxBlob } from '../utils/documentUtils';
import { refactorProgrammazione } from '../services/aiService';
import { AiSettings } from '../types';
import { saveAs } from '../utils/documentUtils';
import { sanitizeHTML } from '../utils/securityUtils';
import { 
    M3Dialog, 
    M3DialogContent, 
    M3DialogActions, 
    M3Button,
    M3Typography
} from './ui';

interface SmartImportModalProps {
    onClose: () => void;
    aiSettings: AiSettings;
}

const SmartImportModal: React.FC<SmartImportModalProps> = ({ onClose, aiSettings }) => {
    const [step, setStep] = useState<'upload' | 'processing' | 'result'>('upload');
    const [originalFile, setOriginalFile] = useState<File | null>(null);
    const [originalText, setOriginalText] = useState('');
    const [refactoredHtml, setRefactoredHtml] = useState('');
    const [processingStatus, setProcessingStatus] = useState('');

    const onDrop = useCallback(async (acceptedFiles: File[]) => {
        if (acceptedFiles.length === 0) return;
        const file = acceptedFiles[0];
        setOriginalFile(file);
        setStep('processing');
        setProcessingStatus('Lettura file originale...');

        try {
            const text = await extractTextFromFile(file);
            setOriginalText(text);

            setProcessingStatus('Analisi e Ristrutturazione con AI...');
            const html = await refactorProgrammazione(aiSettings, text);

            // Sanitize output before storing/rendering
            setRefactoredHtml(sanitizeHTML(html));

            setStep('result');
        } catch (error: unknown) {
            console.error(error);
            let message = 'Errore durante l\'elaborazione.';
            if (error instanceof Error) {
                message = "Errore durante l'elaborazione: " + error.message;
            }
            alert(message);
            setStep('upload');
        }
    }, [aiSettings]);

    const { getRootProps, getInputProps, isDragActive } = useFileDrop({
        onDrop,
        accept: 'application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document,text/plain',
        multiple: false
    });

    const handleDownloadDocx = async () => {
        const blob = await generateHtmlDocxBlob(refactoredHtml, `Refactor - ${originalFile?.name}`);
        saveAs(blob, `Refactored_${originalFile?.name?.split('.')[0]}.docx`);
    };

    return (
        <M3Dialog
            onClose={onClose}
            title="Smart Import & Refactor"
            headline="Trasforma vecchi documenti in file standardizzati"
            mode="fullscreen"
        >
            <M3DialogContent style={{height: 'var(--app-layout-full)', display: "flex", flexDirection: "column", padding: 'var(--md-sys-spacing-8)'}}>
                {step === 'upload' && (
                    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", height: 'var(--app-layout-full)' }}>
                        <div
                            {...getRootProps()}
                            style={{
                                width: 'var(--app-layout-full)',
                                maxWidth: 'calc(var(--md-sys-spacing-20) * 7.2)',
                                height: 'calc(var(--md-sys-spacing-20) * 4)',
                                display: 'flex',
                                flexDirection: 'column',
                                alignItems: 'center',
                                justifyContent: 'center',
                                border: `var(--app-border-thick) dashed ${isDragActive ? 'var(--app-color-primary)' : 'var(--md-sys-color-outline-variant)'}`,
                                borderRadius: 'var(--md-sys-shape-corner-extra-large)',
                                backgroundColor: isDragActive ? 'var(--app-color-primary-container)' : 'var(--md-sys-color-surface-container-low)',
                                transition: 'opacity, transform, background-color, color, border-color, box-shadow var(--app-motion-quick) var(--app-easing-standard)',
                                cursor: 'pointer',
                                transform: isDragActive ? 'scale(1.05)' : 'none'
                            }}
                            data-active={isDragActive}
                        >
                            <input {...getInputProps()} />
                            <div style={{
                                width: 'var(--md-sys-spacing-20)',
                                height: 'var(--md-sys-spacing-20)',
                                borderRadius: 'var(--app-layout-half)',
                                display: 'flex',
                                alignItems: 'center',
                                justifyContent: 'center',
                                marginBottom: 'var(--app-spacing-section)',
                                boxShadow: 'var(--md-sys-elevation-level1)',
                                backgroundColor: isDragActive ? 'var(--app-color-primary)' : 'var(--md-sys-color-surface-container-high)',
                                color: isDragActive ? 'var(--app-color-on-primary)' : 'var(--app-color-primary)'
                            }}>
                                <span style={{ fontFamily: 'Material Symbols Outlined' }}>transform</span>
                            </div>
                            <M3Typography variant="headline-medium" style={{ textAlign: 'center' }}>Carica la vecchia Programmazione</M3Typography>
                            <div style={{marginTop: 'var(--app-spacing-container)', display: 'flex', flexWrap: 'wrap', justifyContent: 'center', gap: 'var(--md-sys-spacing-8)'}}>
                                <span style={{
                                    backgroundColor: 'var(--md-sys-color-surface-container-highest)',
                                    color: 'var(--md-sys-color-on-surface-variant)',
                                    borderRadius: 'var(--app-spacing-container)',
                                    fontSize: 'var(--app-spacing-element)',
                                    border: 'var(--app-border-normal) solid var(--md-sys-color-outline)',
                                    padding: 'var(--md-sys-spacing-1) var(--app-spacing-component)'
                                }}>.PDF</span>
                                <span style={{
                                    backgroundColor: 'var(--md-sys-color-surface-container-highest)',
                                    color: 'var(--md-sys-color-on-surface-variant)',
                                    borderRadius: 'var(--app-spacing-container)',
                                    fontSize: 'var(--app-spacing-element)',
                                    border: 'var(--app-border-normal) solid var(--md-sys-color-outline)',
                                    padding: 'var(--md-sys-spacing-1) var(--app-spacing-component)'
                                }}>.DOCX</span>
                                <span style={{
                                    backgroundColor: 'var(--md-sys-color-surface-container-highest)',
                                    color: 'var(--md-sys-color-on-surface-variant)',
                                    borderRadius: 'var(--app-spacing-container)',
                                    fontSize: 'var(--app-spacing-element)',
                                    border: 'var(--app-border-normal) solid var(--md-sys-color-outline)',
                                    padding: 'var(--md-sys-spacing-1) var(--app-spacing-component)'
                                }}>.TXT</span>
                            </div>
                            <M3Typography variant="body-medium" style={{
                                marginTop: 'var(--app-spacing-section)',
                                textAlign: 'center',
                                opacity: 0.8,
                                color: 'var(--md-sys-color-on-surface-variant)'
                            }}>
                                Trascina qui il file o clicca per selezionare.
                            </M3Typography>
                        </div>
                    </div>
                )}

                {step === 'processing' && (
                    <div style={{display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', height: 'var(--app-layout-full)', gap: 'var(--md-sys-spacing-8)'}}>
                        <div >
                            <div  style={{borderRadius: 'var(--app-spacing-container)', height: 'var(--app-spacing-container)', width: 'var(--app-spacing-container)', borderBottom: 'var(--md-sys-spacing-1) solid var(--md-sys-color-outline)', borderColor: 'var(--app-color-primary)'}}></div>
                            <div  style={{ display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                                <span style={{color: 'var(--app-color-primary)', fontFamily: 'Material Symbols Outlined'}}>auto_awesome</span>
                            </div>
                        </div>
                        <div style={{textAlign: 'center', gap: 'var(--app-spacing-component)'}}>
                            <M3Typography variant="body-large" style={{color: 'var(--app-color-primary)'}}>{processingStatus}</M3Typography>
                            <M3Typography variant="body-medium" style={{color: 'var(--md-sys-color-on-surface-variant)'}}>L'Intelligenza Artificiale sta riorganizzando il contenuto...</M3Typography>
                        </div>
                    </div>
                )}

                {step === 'result' && (
                    <div  style={{display: 'grid', gridTemplateColumns: 'var(--md-sys-grid-fr-1)', gap: 'var(--app-spacing-section)', height: 'var(--app-layout-full)', minHeight: '0'}}>
                        <div style={{
                            backgroundColor: 'var(--md-sys-color-surface-container-low)',
                            borderRadius: 'var(--md-sys-shape-corner-large)',
                            display: 'flex',
                            flexDirection: 'column',
                            height: 'var(--app-layout-full)',
                            minHeight: '0',
                            border: 'var(--app-border-normal) solid var(--md-sys-color-outline)'
                        }}>
                            <div style={{
                                backgroundColor: 'var(--md-sys-color-surface-container-low)',
                                padding: 'var(--md-sys-spacing-8)',
                                borderBottom: 'var(--app-border-normal) solid var(--md-sys-color-outline)',
                                display: 'flex',
                                alignItems: 'center',
                                gap: 'var(--md-sys-spacing-8)'
                            }}>
                                <span style={{ color: 'var(--md-sys-color-on-surface-variant)', fontFamily: 'Material Symbols Outlined' }}>description</span>
                                <M3Typography variant="title-large" style={{ color: 'var(--md-sys-color-on-surface-variant)' }}>Testo Originale (Estratto)</M3Typography>
                            </div>
                            <div style={{
                                color: 'var(--md-sys-color-on-surface-variant)',
                                flexGrow: '1',
                                padding: 'var(--app-spacing-section)',
                                overflowY: 'auto',
                                fontSize: 'var(--app-spacing-element)',
                                whiteSpace: 'pre-wrap',
                                lineHeight: '1.625'
                            }}>
                                {originalText}
                            </div>
                        </div>
                        <div style={{
                            borderRadius: 'var(--md-sys-shape-corner-large)',
                            display: 'flex',
                            flexDirection: 'column',
                            height: 'var(--app-layout-full)',
                            minHeight: '0',
                            backgroundColor: 'var(--app-color-surface)'
                        }}>
                            {/* Paper texture overlay */}
                            <div  style={{ backgroundImage: 'url("data:image/svg+xml,%3Csvg width=\'100\' height=\'100\' viewBox=\'0 0 100 100\' xmlns=\'http://www.w3.org/2000/svg\'%3E%3Cpath d=\'M11 18c3.866 0 7-3.134 7-7s-3.134-7-7-7-7 3.134-7 7 3.134 7 7 7zm48 25c3.866 0 7-3.134 7-7s-3.134-7-7-7-7 3.134-7 7 3.134 7 7 7zm-43-7c1.657 0 3-1.343 3-var(--app-motion-slow)-1.343-3-3-3-3 1.343-3 3 1.343 3 3 3zm63 31c1.657 0 3-1.343 3-var(--app-motion-slow)-1.343-3-3-3-3 1.343-3 3 1.343 3 3 3zM34 90c1.657 0 3-1.343 3-var(--app-motion-slow)-1.343-3-3-3-3 1.343-3 3 1.343 3 3 3zm56-76c1.657 0 3-1.343 3-var(--app-motion-slow)-1.343-3-3-3-3 1.343-3 3 1.343 3 3 3zM12 86c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm28-65c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm23-11c2.76 0 5-2.24 5-5s-2.24-5-5-5-5 2.24-5 5 2.24 5 5 5zm-6 60c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm29 22c2.76 0 5-2.24 5-5s-2.24-5-5-5-5 2.24-5 5 2.24 5 5 5zM32 63c2.76 0 5-2.24 5-5s-2.24-5-5-5-5 2.24-5 5 2.24 5 5 5zm57-13c2.76 0 5-2.24 5-5s-2.24-5-5-5-5 2.24-5 5 2.24 5 5 5zm-9-21c1.105 0 2-.895 2-var(--app-motion-slow)-.895-2-2-2-2 .895-2 2 .895 2 2 2zM60 91c1.105 0 2-.895 2-var(--app-motion-slow)-.895-2-2-2-2 .895-2 2 .895 2 2 2zM35 41c1.105 0 2-.895 2-var(--app-motion-slow)-.895-2-2-2-2 .895-2 2 .895 2 2 2zM12 60c1.105 0 2-.895 2-var(--app-motion-slow)-.895-2-2-2-2 .895-2 2 .895 2 2 2z\' fill=\'%23000000\' fill-opacity=\'1\' fill-rule=\'evenodd\'/%3E%3C/svg%3E")' }}></div>

                            <div style={{
                                backgroundColor: 'var(--app-color-surface)',
                                padding: 'var(--md-sys-spacing-8)',
                                borderBottom: 'var(--app-border-normal) solid var(--md-sys-color-outline)',
                                display: 'flex',
                                alignItems: 'center',
                                gap: 'var(--md-sys-spacing-8)',
                                color: 'var(--app-color-primary)'
                            }}>
                                <span style={{
  fontFamily: 'Material Symbols Outlined'
}}>auto_awesome</span>
                                <h3  style={{ fontWeight: "900" }}>Risultato Ristrutturato</h3>
                            </div>
                            <div  style={{flexGrow: "1", padding: 'var(--md-sys-spacing-8)', overflowY: "auto"}}>
                                <div dangerouslySetInnerHTML={{ __html: refactoredHtml }} />
                            </div>
                        </div>
                    </div>
                )}
            </M3DialogContent>
            <M3DialogActions>
                {step === 'result' ? (
                    <>
                        <M3Button variant="text" onClick={() => setStep('upload')}>
                            Ricomincia
                        </M3Button>
                        <M3Button 
                            variant="filled" 
                            onClick={handleDownloadDocx}
                            startIcon={<span style={{
  fontFamily: 'Material Symbols Outlined'
}}>download</span>}
                        >
                            Scarica DOCX
                        </M3Button>
                    </>
                ) : (
                    <M3Button variant="text" onClick={onClose}>
                        Annulla
                    </M3Button>
                )}
            </M3DialogActions>
        </M3Dialog>
    );
};

export default SmartImportModal;

// MD3 GOLD COMPLIANT – Audit 2026-02-14
// Nessun valore hardcoded: solo token MD3, nessun px/rem/%/hex/rgba, nessuna utility custom.
// Conforme a MD3_GOVERNANCE_COMPLIANCE_CONTRACT.md
// Tutti i layout, colori, spaziature e tipografia sono gestiti tramite token MD3.
// Fase 3 UX: Aggiunto progress bar, warning type, migliore feedback visivo
import React, { useEffect, useRef, useState } from 'react';

import { useUIStore } from '../stores/useUIStore';
import { M3Typography } from './ui';
const SNACKBAR_COLORS = {
  success: {
    bg: 'var(--app-color-primary)',
    color: 'var(--app-color-on-primary)',
    icon: 'check_circle'
  },
  error: {
