// MD3 Gold Compliant
// Card con swipe actions (delete, archive, etc.)
// Audit: febbraio 2026

import React, { useState, useRef } from 'react';

interface SwipeAction {
  label: string;
  icon: string;
  color: string;
  backgroundColor: string;
  onAction: () => void;
}

interface SwipeableCardProps {
  children: React.ReactNode;
  leftAction?: SwipeAction;
  rightAction?: SwipeAction;
  threshold?: number; // px to trigger action
  disabled?: boolean;
}

export const SwipeableCard: React.FC<SwipeableCardProps> = ({
  children,
  leftAction,
  rightAction,
  threshold = 80,
  disabled = false
}) => {
  const [translateX, setTranslateX] = useState(0);
  const [isDragging, setIsDragging] = useState(false);
  const [actionTriggered, setActionTriggered] = useState(false);
  const startX = useRef(0);
  const currentX = useRef(0);
  const cardRef = useRef<HTMLDivElement>(null);

  const handleTouchStart = (e: React.TouchEvent) => {
    if (disabled) return;
    setIsDragging(true);
    startX.current = e.touches[0].clientX;
    currentX.current = translateX;
  };

  const handleTouchMove = (e: React.TouchEvent) => {
    if (!isDragging || disabled) return;
    const deltaX = e.touches[0].clientX - startX.current;
    const newTranslateX = currentX.current + deltaX;

    // Limit swipe distance
    const maxSwipe = 120;
    const limitedTranslateX = Math.max(-maxSwipe, Math.min(maxSwipe, newTranslateX));

    // Check if action should be triggered
    if (leftAction && limitedTranslateX >= threshold) {
      setActionTriggered(true);
    } else if (rightAction && limitedTranslateX <= -threshold) {
      setActionTriggered(true);
    } else {
      setActionTriggered(false);
    }

    setTranslateX(limitedTranslateX);
  };

  const handleTouchEnd = () => {
    if (disabled) return;
    setIsDragging(false);

    // Trigger action if threshold reached
    if (leftAction && translateX >= threshold && actionTriggered) {
      leftAction.onAction();
      setTranslateX(0);
    } else if (rightAction && translateX <= -threshold && actionTriggered) {
      rightAction.onAction();
      setTranslateX(0);
    } else {
      // Reset position
      setTranslateX(0);
    }

    setActionTriggered(false);
  };

  const showLeftAction = leftAction && translateX > 0;
  const showRightAction = rightAction && translateX < 0;

  return (
    <div
      style={{
        position: 'relative',
        overflow: 'hidden',
        borderRadius: 'var(--md-sys-spacing-2)',
        touchAction: disabled ? 'auto' : 'pan-y'
      }}
    >
      {/* Left Action */}
      {showLeftAction && (
        <div
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            bottom: 0,
            width: Math.abs(translateX),
            backgroundColor: leftAction.backgroundColor,
            display: 'flex',
            alignItems: 'center',
            paddingLeft: 'var(--md-sys-spacing-4)',
            gap: 'var(--md-sys-spacing-2)',
            opacity: actionTriggered ? 1 : 0.7,
            transition: 'opacity 150ms'
          }}
        >
          <span
            className="material-symbols-outlined"
            style={{
              fontSize: '24px',
              color: leftAction.color,
              fontVariationSettings: '"FILL" 1, "wght" 600'
            }}
          >
            {leftAction.icon}
          </span>
          <span
            style={{
              color: leftAction.color,
              fontWeight: '600',
              fontSize: '14px'
            }}
          >
            {leftAction.label}
          </span>
        </div>
      )}

      {/* Right Action */}
      {showRightAction && (
        <div
          style={{
            position: 'absolute',
            top: 0,
            right: 0,
            bottom: 0,
            width: Math.abs(translateX),
            backgroundColor: rightAction.backgroundColor,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'flex-end',
            paddingRight: 'var(--md-sys-spacing-4)',
            gap: 'var(--md-sys-spacing-2)',
            opacity: actionTriggered ? 1 : 0.7,
            transition: 'opacity 150ms'
          }}
        >
          <span
            style={{
              color: rightAction.color,
              fontWeight: '600',
              fontSize: '14px'
            }}
          >
            {rightAction.label}
          </span>
          <span
            className="material-symbols-outlined"
            style={{
              fontSize: '24px',
              color: rightAction.color,
              fontVariationSettings: '"FILL" 1, "wght" 600'
            }}
          >
            {rightAction.icon}
          </span>
        </div>
      )}

      {/* Card Content */}
      <div
        ref={cardRef}
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
        style={{
          transform: `translateX(${translateX}px)`,
          transition: isDragging ? 'none' : 'transform 250ms var(--md-sys-motion-easing-standard)',
          backgroundColor: 'var(--md-sys-color-surface-container)',
          cursor: disabled ? 'default' : 'grab',
          userSelect: 'none'
        }}
      >
        {children}
      </div>
    </div>
  );
};

export default SwipeableCard;

// MD3 Gold Compliant
// Theme toggle button con icon animation
// Audit: febbraio 2026

import React, { useState } from 'react';
import { useTheme } from '../../contexts/ThemeContext';
import { Tooltip } from './index';

interface ThemeToggleProps {
  variant?: 'icon' | 'button' | 'menu';
  showLabel?: boolean;
}

export const ThemeToggle: React.FC<ThemeToggleProps> = ({
  variant = 'icon',
  showLabel = false
}) => {
  const { mode, setMode, effectiveTheme, isSystemTheme } = useTheme();
  const [isAnimating, setIsAnimating] = useState(false);

  const handleToggle = () => {
    setIsAnimating(true);

    // Cycle through: auto → light → dark → auto
    if (mode === 'auto') {
      setMode('light');
    } else if (mode === 'light') {
      setMode('dark');
    } else {
      setMode('auto');
    }

    setTimeout(() => setIsAnimating(false), 400);
  };

  // Icon based on current effective theme
  const icon = effectiveTheme === 'dark' ? 'dark_mode' : 'light_mode';

  // Label based on mode
  const label = mode === 'auto' 
    ? 'Tema automatico' 
    : mode === 'light' 
      ? 'Tema chiaro' 
      : 'Tema scuro';

  // Tooltip text
  const tooltipText = mode === 'auto'
    ? `Tema automatico (${effectiveTheme === 'dark' ? 'Scuro' : 'Chiaro'})`
    : mode === 'light'
      ? 'Passa a tema scuro'
      : 'Passa a tema automatico';

  if (variant === 'icon') {
    return (
      <Tooltip text={tooltipText}>
        <button
          onClick={handleToggle}
          aria-label={label}
          style={{
            position: 'relative',
            width: 'var(--md-sys-spacing-10)',
            height: 'var(--md-sys-spacing-10)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            border: 'none',
            borderRadius: '50%',
            backgroundColor: 'transparent',
            color: 'var(--md-sys-color-on-surface)',
            cursor: 'pointer',
            transition: 'background-color 200ms',
            overflow: 'hidden'
          }}
          onMouseEnter={(e) => {
            e.currentTarget.style.backgroundColor = 'var(--md-sys-color-surface-variant)';
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.backgroundColor = 'transparent';
          }}
        >
          {/* Icon with rotation animation */}
          <span
            className="material-symbols-outlined"
            style={{
              fontSize: '24px',
              fontVariationSettings: isSystemTheme 
                ? '"FILL" 0, "wght" 400' 
                : '"FILL" 1, "wght" 600',
              transform: isAnimating ? 'rotate(360deg)' : 'rotate(0deg)',
              transition: 'transform 400ms var(--md-sys-motion-easing-standard)'
            }}
          >
            {icon}
          </span>

          {/* System indicator dot */}
          {isSystemTheme && (
            <div
              style={{
                position: 'absolute',
                bottom: 'var(--md-sys-spacing-1)',
                right: 'var(--md-sys-spacing-1)',
                width: 'var(--md-sys-spacing-1)',
                height: 'var(--md-sys-spacing-1)',
                borderRadius: '50%',
                backgroundColor: 'var(--md-sys-color-primary)',
                boxShadow: '0 0 4px var(--md-sys-color-primary)'
              }}
            />
          )}
        </button>
      </Tooltip>
    );
  }

  if (variant === 'button') {
    return (
      <button
        onClick={handleToggle}
        aria-label={label}
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: 'var(--md-sys-spacing-2)',
          padding: 'var(--md-sys-spacing-2) var(--md-sys-spacing-4)',
          border: '1px solid var(--md-sys-color-outline)',
          borderRadius: 'var(--md-sys-spacing-5)',
          backgroundColor: 'var(--md-sys-color-surface-container)',
          color: 'var(--md-sys-color-on-surface)',
          fontSize: '14px',
          fontWeight: '500',
          cursor: 'pointer',
          transition: 'all 200ms'
        }}
        onMouseEnter={(e) => {
          e.currentTarget.style.backgroundColor = 'var(--md-sys-color-surface-container-high)';
        }}
        onMouseLeave={(e) => {
          e.currentTarget.style.backgroundColor = 'var(--md-sys-color-surface-container)';
        }}
      >
        <span
          className="material-symbols-outlined"
          style={{
            fontSize: '20px',
            fontVariationSettings: isSystemTheme 
              ? '"FILL" 0, "wght" 400' 
              : '"FILL" 1, "wght" 600',
            transform: isAnimating ? 'rotate(360deg)' : 'rotate(0deg)',
            transition: 'transform 400ms var(--md-sys-motion-easing-standard)'
          }}
        >
          {icon}
        </span>
        {showLabel && <span>{label}</span>}
      </button>
    );
  }

  // variant === 'menu'
  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--md-sys-spacing-1)'
      }}
    >
      {/* Menu items for each theme option */}
      {(['auto', 'light', 'dark'] as const).map((themeMode) => (
        <button
          key={themeMode}
          onClick={() => setMode(themeMode)}
          aria-pressed={mode === themeMode}
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: 'var(--md-sys-spacing-3)',
            padding: 'var(--md-sys-spacing-3) var(--md-sys-spacing-4)',
            border: 'none',
            borderRadius: 'var(--md-sys-spacing-2)',
            backgroundColor: mode === themeMode 
              ? 'var(--md-sys-color-primary-container)' 
              : 'transparent',
            color: mode === themeMode
              ? 'var(--md-sys-color-on-primary-container)'
              : 'var(--md-sys-color-on-surface)',
            fontSize: '14px',
            fontWeight: mode === themeMode ? '600' : '400',
            cursor: 'pointer',
            textAlign: 'left',
            width: '100%',
            transition: 'all 200ms'
          }}
          onMouseEnter={(e) => {
            if (mode !== themeMode) {
              e.currentTarget.style.backgroundColor = 'var(--md-sys-color-surface-variant)';
            }
          }}
          onMouseLeave={(e) => {
            if (mode !== themeMode) {
              e.currentTarget.style.backgroundColor = 'transparent';
            }
          }}
        >
          {/* Icon */}
          <span
            className="material-symbols-outlined"
            style={{
              fontSize: '20px',
              fontVariationSettings: mode === themeMode 
                ? '"FILL" 1, "wght" 600' 
                : '"FILL" 0, "wght" 400'
            }}
          >
            {themeMode === 'auto' ? 'brightness_auto' : themeMode === 'light' ? 'light_mode' : 'dark_mode'}
          </span>

          {/* Label */}
          <span style={{ flex: 1 }}>
            {themeMode === 'auto' ? 'Automatico' : themeMode === 'light' ? 'Chiaro' : 'Scuro'}
          </span>

          {/* Checkmark */}
          {mode === themeMode && (
            <span
              className="material-symbols-outlined"
              style={{
                fontSize: '18px',
                fontVariationSettings: '"FILL" 1, "wght" 600'
              }}
            >
              check
            </span>
          )}
        </button>
      ))}
    </div>
  );
};

export default ThemeToggle;

// MD3 Gold Compliant
// Tooltip accessibile con aria-describedby
// Audit: febbraio 2026

import React, { useState, useRef, useId } from 'react';

interface TooltipProps {
  content: string;
  children: React.ReactElement;
  position?: 'top' | 'bottom' | 'left' | 'right';
  delay?: number;
}

export const Tooltip: React.FC<TooltipProps> = ({
  content,
  children,
  position = 'top',
  delay = 500
}) => {
  const [isVisible, setIsVisible] = useState(false);
  const [isFocused, setIsFocused] = useState(false);
  const timeoutRef = useRef<NodeJS.Timeout>();
  const tooltipId = useId();

  const showTooltip = () => {
    timeoutRef.current = setTimeout(() => {
      setIsVisible(true);
    }, delay);
  };

  const hideTooltip = () => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }
    setIsVisible(false);
  };

  const positionStyles = {
    top: {
      bottom: '100%',
      left: '50%',
      transform: 'translateX(-50%) translateY(-8px)',
      marginBottom: 'var(--md-sys-spacing-2)'
    },
    bottom: {
      top: '100%',
      left: '50%',
      transform: 'translateX(-50%) translateY(8px)',
      marginTop: 'var(--md-sys-spacing-2)'
    },
    left: {
      right: '100%',
      top: '50%',
      transform: 'translateY(-50%) translateX(-8px)',
      marginRight: 'var(--md-sys-spacing-2)'
    },
    right: {
      left: '100%',
      top: '50%',
      transform: 'translateY(-50%) translateX(8px)',
      marginLeft: 'var(--md-sys-spacing-2)'
    }
  };

  // Clone children e aggiungi props per accessibilità
  const childrenWithProps = React.cloneElement(children, {
    onMouseEnter: (e: React.MouseEvent) => {
      showTooltip();
      children.props.onMouseEnter?.(e);
    },
    onMouseLeave: (e: React.MouseEvent) => {
      hideTooltip();
      children.props.onMouseLeave?.(e);
    },
    onFocus: (e: React.FocusEvent) => {
      setIsFocused(true);
      showTooltip();
      children.props.onFocus?.(e);
    },
    onBlur: (e: React.FocusEvent) => {
      setIsFocused(false);
      hideTooltip();
      children.props.onBlur?.(e);
    },
    'aria-describedby': isVisible || isFocused ? tooltipId : undefined
  });

  return (
    <div style={{ position: 'relative', display: 'inline-block' }}>
      {childrenWithProps}

      {(isVisible || isFocused) && (
        <div
          id={tooltipId}
          role="tooltip"
          style={{
            position: 'absolute',
            zIndex: 1000,
            padding: 'var(--md-sys-spacing-2) var(--md-sys-spacing-3)',
            background: 'var(--md-sys-color-inverse-surface)',
            color: 'var(--md-sys-color-inverse-on-surface)',
            borderRadius: 'var(--md-sys-spacing-1)',
            boxShadow: '0 4px 8px rgba(0,0,0,0.2)',
            maxWidth: 'var(--md-sys-spacing-16)',
            whiteSpace: 'normal',
            fontSize: 'var(--md-sys-typescale-body-small-size)',
            fontWeight: '500',
            lineHeight: '1.4',
            pointerEvents: 'none',
            animation: 'tooltip-fade-in 200ms ease-out',
            ...positionStyles[position]
          }}
        >
          {content}

          {/* Arrow */}
          <div
            style={{
              position: 'absolute',
              width: 0,
              height: 0,
              borderStyle: 'solid',
              ...(position === 'top' && {
                bottom: '-6px',
                left: '50%',
                transform: 'translateX(-50%)',
                borderWidth: '6px 6px 0 6px',
                borderColor: 'var(--md-sys-color-inverse-surface) transparent transparent transparent'
              }),
              ...(position === 'bottom' && {
                top: '-6px',
                left: '50%',
                transform: 'translateX(-50%)',
                borderWidth: '0 6px 6px 6px',
                borderColor: 'transparent transparent var(--md-sys-color-inverse-surface) transparent'
              }),
              ...(position === 'left' && {
                right: '-6px',
                top: '50%',
                transform: 'translateY(-50%)',
                borderWidth: '6px 0 6px 6px',
                borderColor: 'transparent transparent transparent var(--md-sys-color-inverse-surface)'
              }),
              ...(position === 'right' && {
                left: '-6px',
                top: '50%',
                transform: 'translateY(-50%)',
                borderWidth: '6px 6px 6px 0',
                borderColor: 'transparent var(--md-sys-color-inverse-surface) transparent transparent'
              })
            }}
          />
        </div>
      )}

      <style>{`
        @keyframes tooltip-fade-in {
          from {
            opacity: 0;
            transform: ${position === 'top' ? 'translateX(-50%) translateY(-4px)' :
                         position === 'bottom' ? 'translateX(-50%) translateY(4px)' :
                         position === 'left' ? 'translateY(-50%) translateX(-4px)' :
                         'translateY(-50%) translateX(4px)'};
          }
          to {
            opacity: 1;
            transform: ${position === 'top' ? 'translateX(-50%) translateY(-8px)' :
                         position === 'bottom' ? 'translateX(-50%) translateY(8px)' :
                         position === 'left' ? 'translateY(-50%) translateX(-8px)' :
                         'translateY(-50%) translateX(8px)'};
          }
        }
      `}</style>
    </div>
  );
};

export default Tooltip;

// MD3 Gold Compliant
// Button ottimizzato per touch con ripple effect
// Audit: febbraio 2026

import React, { useState, useRef } from 'react';

interface TouchButtonProps {
  children: React.ReactNode;
  onClick: () => void;
  variant?: 'filled' | 'outlined' | 'text';
  size?: 'small' | 'medium' | 'large';
  disabled?: boolean;
  fullWidth?: boolean;
  icon?: string;
  loading?: boolean;
}

export const TouchButton: React.FC<TouchButtonProps> = ({
  children,
  onClick,
  variant = 'filled',
  size = 'medium',
  disabled = false,
  fullWidth = false,
  icon,
  loading = false
}) => {
  const [ripples, setRipples] = useState<Array<{ x: number; y: number; id: number }>>([]);
  const [isPressed, setIsPressed] = useState(false);
  const buttonRef = useRef<HTMLButtonElement>(null);
  const rippleIdRef = useRef(0);

  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (disabled || loading) return;

    // Create ripple effect
    const button = buttonRef.current;
    if (button) {
      const rect = button.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      const id = rippleIdRef.current++;

      setRipples(prev => [...prev, { x, y, id }]);

      // Remove ripple after animation
      setTimeout(() => {
        setRipples(prev => prev.filter(r => r.id !== id));
      }, 600);
    }

    onClick();
  };

  // Size mapping
  const sizeMap = {
    small: {
      minHeight: 'var(--md-sys-spacing-9)',
      padding: 'var(--md-sys-spacing-2) var(--md-sys-spacing-4)',
      fontSize: '14px'
    },
    medium: {
      minHeight: 'var(--md-sys-spacing-12)',
      padding: 'var(--md-sys-spacing-3) var(--md-sys-spacing-6)',
      fontSize: '16px'
    },
    large: {
      minHeight: 'var(--md-sys-spacing-14)',
      padding: 'var(--md-sys-spacing-4) var(--md-sys-spacing-8)',
      fontSize: '18px'
    }
  }[size];

  // Variant styles
  const variantStyles = {
    filled: {
      backgroundColor: disabled 
        ? 'var(--md-sys-color-surface-variant)' 
        : 'var(--md-sys-color-primary)',
      color: disabled 
        ? 'var(--md-sys-color-on-surface-variant)' 
        : 'var(--md-sys-color-on-primary)',
      border: 'none'
    },
    outlined: {
      backgroundColor: 'transparent',
      color: disabled 
        ? 'var(--md-sys-color-on-surface-variant)' 
        : 'var(--md-sys-color-primary)',
      border: `2px solid ${disabled ? 'var(--md-sys-color-outline-variant)' : 'var(--md-sys-color-primary)'}`
    },
    text: {
      backgroundColor: 'transparent',
      color: disabled 
        ? 'var(--md-sys-color-on-surface-variant)' 
        : 'var(--md-sys-color-primary)',
      border: 'none'
    }
  }[variant];

  return (
    <button
      ref={buttonRef}
      onClick={handleClick}
      onTouchStart={() => setIsPressed(true)}
      onTouchEnd={() => setIsPressed(false)}
      onMouseDown={() => setIsPressed(true)}
      onMouseUp={() => setIsPressed(false)}
      onMouseLeave={() => setIsPressed(false)}
      disabled={disabled || loading}
      style={{
        position: 'relative',
        overflow: 'hidden',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        gap: 'var(--md-sys-spacing-2)',
        width: fullWidth ? '100%' : 'auto',
        minHeight: sizeMap.minHeight,
        padding: sizeMap.padding,
        fontSize: sizeMap.fontSize,
        fontWeight: '600',
        borderRadius: 'var(--md-sys-spacing-5)',
        cursor: disabled || loading ? 'not-allowed' : 'pointer',
        transition: 'all 200ms var(--md-sys-motion-easing-standard)',
        transform: isPressed && !disabled && !loading ? 'scale(0.98)' : 'scale(1)',
        opacity: disabled ? 0.5 : 1,
        userSelect: 'none',
        WebkitTapHighlightColor: 'transparent',
        touchAction: 'manipulation',
        ...variantStyles
      }}
    >
      {/* Loading spinner */}
      {loading && (
        <div
          style={{
            width: '20px',
            height: '20px',
            border: '2px solid currentColor',
            borderTopColor: 'transparent',
            borderRadius: '50%',
            animation: 'spin 0.8s linear infinite'
          }}
        />
      )}

      {/* Icon */}
      {icon && !loading && (
        <span
          className="material-symbols-outlined"
          style={{
            fontSize: '20px',
            fontVariationSettings: '"FILL" 0, "wght" 600'
          }}
        >
          {icon}
        </span>
      )}

      {/* Label */}
      <span>{children}</span>

      {/* Ripple effects */}
      {ripples.map(ripple => (
        <span
          key={ripple.id}
          style={{
            position: 'absolute',
            left: ripple.x,
            top: ripple.y,
            width: '10px',
            height: '10px',
            borderRadius: '50%',
            backgroundColor: 'rgba(255, 255, 255, 0.6)',
            transform: 'translate(-50%, -50%)',
            animation: 'ripple-expand 600ms ease-out',
            pointerEvents: 'none'
          }}
        />
      ))}

      <style>{`
        @keyframes ripple-expand {
          from {
            transform: translate(-50%, -50%) scale(0);
            opacity: 1;
          }
          to {
            transform: translate(-50%, -50%) scale(10);
            opacity: 0;
          }
        }
        @keyframes spin {
          from { transform: rotate(0deg); }
          to { transform: rotate(360deg); }
        }
      `}</style>
    </button>
  );
};

export default TouchButton;
